// Builds plugins/tstack/skills from an upstream tstack checkout plus the local overlays.
//
//   node plugins/tstack/sync.mjs [--source <tstack checkout>] [--check]
//
// Upstream skill files are copied byte for byte. For each skill with an overlay in
// plugins/tstack/overlays/<skill>.md, the overlay is appended to that skill's SKILL.md.
// Files under plugins/tstack/extras/<skill>/ are added beside upstream's and may not
// replace an upstream file.
// --check rebuilds in memory and exits 1 when any generated file differs from what is
// on disk, so a hand edit to a generated file is caught. Without --check it writes the
// files and records the upstream commit in UPSTREAM.md.

import { createHash } from 'node:crypto'
import { execFileSync } from 'node:child_process'
import { existsSync, mkdirSync, readdirSync, readFileSync, rmSync, statSync, writeFileSync } from 'node:fs'
import { dirname, join, relative } from 'node:path'
import { fileURLToPath } from 'node:url'

const here = dirname(fileURLToPath(import.meta.url))
const args = process.argv.slice(2)
const check = args.includes('--check')
const sourceAt = args.indexOf('--source')
const source = sourceAt >= 0 ? args[sourceAt + 1] : 'C:/Users/jeffk/Side Projects/tstack'
const upstreamSkills = join(source, 'skills')
const overlays = join(here, 'overlays')
const target = join(here, 'skills')

if (!existsSync(upstreamSkills)) {
  console.error(`No skills folder at ${upstreamSkills}. Pass --source <tstack checkout>.`)
  process.exit(2)
}

function walk(dir) {
  return readdirSync(dir).flatMap(name => {
    const path = join(dir, name)
    return statSync(path).isDirectory() ? walk(path) : [path]
  })
}

const sha = text => createHash('sha256').update(text).digest('hex').slice(0, 12)

const planned = new Map()
for (const file of walk(upstreamSkills)) {
  const rel = relative(upstreamSkills, file)
  let bytes = readFileSync(file)
  const [skill, ...rest] = rel.split(/[\\/]/)
  if (rest.length === 1 && rest[0] === 'SKILL.md') {
    const overlay = join(overlays, `${skill}.md`)
    if (existsSync(overlay)) bytes = Buffer.concat([bytes, Buffer.from('\n'), readFileSync(overlay)])
  }
  planned.set(rel, bytes)
}

// Local additions that upstream does not ship, such as the Windows pr-wait wrapper.
// They land beside the upstream files and never replace one.
const extras = join(here, 'extras')
if (existsSync(extras)) {
  for (const file of walk(extras)) {
    const rel = relative(extras, file)
    if (planned.has(rel)) {
      console.error(`Extra ${rel} would replace an upstream file`)
      process.exit(1)
    }
    planned.set(rel, readFileSync(file))
  }
}

const unknownOverlays = readdirSync(overlays)
  .map(name => name.replace(/\.md$/, ''))
  .filter(skill => !existsSync(join(upstreamSkills, skill, 'SKILL.md')))
if (unknownOverlays.length > 0) {
  console.error(`Overlays with no upstream skill: ${unknownOverlays.join(', ')}`)
  process.exit(1)
}

if (check) {
  const onDisk = existsSync(target) ? walk(target).map(file => relative(target, file)) : []
  const drift = []
  for (const [rel, bytes] of planned) {
    const path = join(target, rel)
    if (!existsSync(path)) drift.push(`missing ${rel}`)
    else if (sha(readFileSync(path)) !== sha(bytes)) drift.push(`differs ${rel}`)
  }
  for (const rel of onDisk) if (!planned.has(rel)) drift.push(`extra ${rel}`)
  if (drift.length > 0) {
    console.error(drift.join('\n'))
    process.exit(1)
  }
  console.log(`tstack skills match upstream plus overlays (${planned.size} files)`)
  process.exit(0)
}

rmSync(target, { recursive: true, force: true })
for (const [rel, bytes] of planned) {
  const path = join(target, rel)
  mkdirSync(dirname(path), { recursive: true })
  writeFileSync(path, bytes)
}
writeFileSync(join(here, 'LICENSE'), readFileSync(join(source, 'LICENSE')))

let commit = 'unknown'
try {
  commit = execFileSync('git', ['-C', source, 'rev-parse', 'HEAD'], { encoding: 'utf8' }).trim()
} catch {}
const lines = [...planned.keys()].sort().map(rel => `| \`${rel.replaceAll('\\', '/')}\` | \`${sha(planned.get(rel))}\` |`)
writeFileSync(
  join(here, 'UPSTREAM.md'),
  [
    '# Upstream',
    '',
    'Generated by `node plugins/tstack/sync.mjs`. Do not edit this file or anything under `skills/` by hand.',
    'Edit `overlays/<skill>.md` and run the script again.',
    '',
    `- Source: https://github.com/t3dotgg/tstack, local checkout \`${source}\``,
    `- Commit: \`${commit}\``,
    '- License: MIT, copied to `LICENSE` in this folder.',
    '',
    '| File | SHA-256 prefix |',
    '|---|---|',
    ...lines,
    '',
  ].join('\n'),
)
console.log(`Wrote ${planned.size} files from ${source} at ${commit.slice(0, 7)}`)
